using Contoso.Services;

namespace Contoso.Services.Tests;

[TestClass]
public sealed class ServiceRegistryTests
{
    private readonly ServiceRegistry _registry = new();

    [TestMethod]
    public void Resolve_RegisteredService_ReturnsSameInstance()
    {
        var service = new TestService();
        _registry.Register<ITestService>(service);

        var resolved = _registry.Resolve<ITestService>();

        Assert.AreSame(service, resolved);
    }

    [TestMethod]
    public void Resolve_UnregisteredService_ReturnsNull()
    {
        var resolved = _registry.Resolve<ITestService>();

        Assert.IsNull(resolved);
    }

    [TestMethod]
    public void GetAll_ContainsRegisteredService()
    {
        var service = new TestService();
        _registry.Register<ITestService>(service);

        var all = _registry.GetAll();

        CollectionAssert.Contains(all.ToList(), service);
    }

    [TestMethod]
    public void GetAll_DoesNotContainRemovedService()
    {
        var service = new TestService();
        _registry.Register<ITestService>(service);
        _registry.Remove<ITestService>();

        var all = _registry.GetAll();

        CollectionAssert.DoesNotContain(all.ToList(), service);
    }

    [TestMethod]
    public void GetAll_IsEmptyBeforeRegistration()
    {
        var all = _registry.GetAll();

        Assert.AreEqual(0, all.Count);
    }

    [TestMethod]
    public void GetAll_IsNotEmptyAfterRegistration()
    {
        _registry.Register<ITestService>(new TestService());

        var all = _registry.GetAll();

        Assert.AreNotEqual(0, all.Count);
    }

    private interface ITestService { }
    private sealed class TestService : ITestService { }
}

